package com.sobrenaturaldirector.derivation;
public final class DerivedSignal { private final String ruleId; private final Double value; private final String label; private final Confidence confidence; private final Provenance provenance; public DerivedSignal(String ruleId,Double value,String label,Confidence confidence,Provenance provenance){this.ruleId=ruleId;this.value=value;this.label=label;this.confidence=confidence;this.provenance=provenance;} public String getRuleId(){return ruleId;} public Double getValue(){return value;} public String getLabel(){return label;} public Confidence getConfidence(){return confidence;} public Provenance getProvenance(){return provenance;} public boolean isKnown(){return value!=null;} }
